"""`main` regenerates `wine_cancelled.ihpo`, the wine-150 exchange's experiment
that the `budget` evals replay: SMAC with LightGBM on the wine demo, balanced
accuracy over five folds, sized for 150 trials and cancelled after 86. The run
goes through Codesigner's own run service, so the file has the runs, the
origins and the design record a real one has. It migrates and fills the
database it is given, so point it at a scratch one:

    DATABASE_URL=sqlite:////tmp/wine.sqlite3 MEDIA_ROOT=/tmp/wine-media \\
        python tests/fixtures/make_wine_fixture.py

The run takes several minutes, so `wine_cancelled.ihpo` is committed and
regenerated by hand after result-format changes.
"""

import os
import sys
from importlib.metadata import version as dist_version
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parent.parent))
os.environ.setdefault("DJANGO_SETTINGS_MODULE", "config.settings")

OUT = HERE / "wine_cancelled.ihpo"
BUDGET = 150
CANCELLED_AT = 86
METRIC = "balanced_accuracy"


def main() -> None:
    import django

    django.setup()
    from django.core.management import call_command

    from core import io, provenance
    from core.metrics import metrics_for
    from core.optimizers import SMACOptimizer
    from core.optimizers.base import PolledFlag
    from experiments.models import Run
    from experiments.services import run as run_service
    from experiments.services import snapshot

    call_command("migrate", verbosity=0)
    exp = snapshot.experiment_from_snapshot({
        "format": io.SNAPSHOT_FORMAT,
        "version": dist_version("codesigner"),
        "name": "wine-150",
        "seed": 0,
        "dataset": {"filename": "wine.csv", "path": "", "demo": "wine",
                    "target_column": "quality"},
        "model": {"kind": "registry", "name": "LightGBM", "path": ""},
        "evaluation": provenance.evaluation(5, task="classification"),
        "metrics": {"names": metrics_for("classification", probabilities=True),
                    "current": None, "original": None},
        "optimizer": {"name": "SMAC", "params": SMACOptimizer().get_params()},
        "result": None,
    })
    run = run_service.create_run(exp, {"max_trials": BUDGET}, METRIC)

    # The flag is read before each trial, uncached, and set once the trial
    # that makes 86 is recorded, so the run ends there as the person's did.
    run_service.PolledFlag = lambda check, ttl=1.0: PolledFlag(check, ttl=0)
    writer = run_service._partial_result_writer

    def cancelling(*args):
        write = writer(*args)

        def record(collector):
            if len(collector.results) >= CANCELLED_AT:
                Run.objects.filter(pk=run.pk).update(cancel_requested=True)
            return write(collector)
        return record

    run_service._partial_result_writer = cancelling
    run_service.execute_run(run.pk)

    run.refresh_from_db()
    exp.refresh_from_db()
    assert run.status == "cancelled" and run.trial_count == CANCELLED_AT, (
        run.status, run.trial_count, run.error)
    OUT.write_bytes(io.to_bytes(snapshot.snapshot_from_experiment(exp, provenance=True)))
    print(f"wrote {OUT} ({OUT.stat().st_size:,} bytes, {run.trial_count} trials)")


if __name__ == "__main__":
    main()
